-- Migration 20260904000009: HSN/SAC Canonical Master Data
BEGIN;
DO $$
DECLARE
    v_country_id UUID;
BEGIN
    SELECT id INTO v_country_id FROM catalog.countries WHERE iso2 = 'IN';

    -- Add hierarchy and source fields if they do not exist
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='catalog' AND table_name='hsn_sac' AND column_name='classification_level') THEN ALTER TABLE catalog.hsn_sac ADD COLUMN classification_level VARCHAR(50); END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='catalog' AND table_name='hsn_sac' AND column_name='code_length') THEN ALTER TABLE catalog.hsn_sac ADD COLUMN code_length INT; END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='catalog' AND table_name='hsn_sac' AND column_name='parent_code') THEN ALTER TABLE catalog.hsn_sac ADD COLUMN parent_code VARCHAR(20); END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='catalog' AND table_name='hsn_sac' AND column_name='is_leaf') THEN ALTER TABLE catalog.hsn_sac ADD COLUMN is_leaf BOOLEAN DEFAULT true; END IF;

    -- Temporary table for UPSERT
    CREATE TEMP TABLE tmp_hsn_sac (
        code VARCHAR(20),
        code_type VARCHAR(10),
        description TEXT,
        chapter VARCHAR(5),
        goods_or_service VARCHAR(10),
        status VARCHAR(50),
        classification_level VARCHAR(50),
        code_length INT,
        parent_code VARCHAR(20)
    ) ON COMMIT DROP;


    -- Update existing or insert new
        country_id, code, code_type, description, chapter, goods_or_service, status, classification_level, code_length, parent_code, is_leaf, official_source, source_reference
    )
    SELECT
        v_country_id, t.code, t.code_type, t.description, t.chapter, t.goods_or_service, t.status, t.classification_level, t.code_length, t.parent_code, true,
        CASE WHEN t.code_type = 'HSN' THEN 'https://tutorial.gst.gov.in/downloads/HSN_SAC.xlsx' ELSE 'https://cbic-gst.gov.in/hindi/pdf/central-tax-rate/Notification11-CGST-Annexure.pdf' END,
        CASE WHEN t.code_type = 'HSN' THEN 'GST Portal Excel 051108e31063f1ef0d6dfb005a622bcc848878fa2d94fae51a73e67f8916871e' ELSE 'Annexure 11/2017 & Notif 12/2023' END
    FROM tmp_hsn_sac t
    ON CONFLICT (country_id, code_type, code) DO UPDATE SET
        description = EXCLUDED.description,
        status = EXCLUDED.status,
        classification_level = EXCLUDED.classification_level,
        code_length = EXCLUDED.code_length,
        parent_code = EXCLUDED.parent_code,
        official_source = EXCLUDED.official_source,
        source_reference = EXCLUDED.source_reference;

    -- Update leaf status (if a code is used as a parent, it is not a leaf)
    UPDATE catalog.hsn_sac p
    SET is_leaf = false
    WHERE p.country_id = v_country_id AND EXISTS (
        SELECT 1 FROM catalog.hsn_sac c WHERE c.parent_code = p.code AND c.country_id = p.country_id AND c.code_type = p.code_type
    );

END $$;
COMMIT;